def transform(grid):
    g = np.array(grid)
    bg = 0
    ys, xs = np.where(g == 5)
    y0, x0, y1, x1 = ys.min(), xs.min(), ys.max(), xs.max()
    H, W = g.shape
    # legend: markers outside the 5-box, shape is the 2x2 of 1s down-right of marker
    shapes = {}
    for y in range(H):
        for x in range(W):
            c = g[y, x]
            if c in (0, 1, 5):
                continue
            if y0 <= y <= y1 and x0 <= x <= x1:
                continue
            win = g[y+1:y+3, x+1:x+3]
            if win.shape == (2, 2) and (win == 1).any():
                shapes[int(c)] = (win == 1)
    out = np.full((y1 - y0 + 1, x1 - x0 + 1), bg, dtype=int)
    emit(out, "Allocate a blank canvas the size of the colour-5 block lattice.")
    for by in range(0, out.shape[0], 3):
        for bx in range(0, out.shape[1], 3):
            blk = g[y0+by:y0+by+2, x0+bx:x0+bx+2]
            cols = [int(v) for v in blk.flatten() if v not in (0, 5)]
            if not cols:
                continue
            c = cols[0]
            if c in shapes:
                sub = out[by:by+2, bx:bx+2]
                sub[shapes[c]] = c
        emit(out, f"Stamp the legend shapes for the blocks in block row {by // 3 + 1}.")
    emit(out, "Final grid: every marked block replaced by its colour's legend shape.")
    return out
